<div class="page-head"><div><span class="eyebrow dark">RouterOS REST</span><h1><?= e(tr('روترها', 'Routers')) ?></h1><p><?= e(tr('مدیریت اتصال و همگام‌سازی روترهای MikroTik', 'Manage MikroTik connections and synchronization')) ?></p></div><?php if(Auth::isSuperadmin()):?><a class="button primary" href="<?= e(url('router-form')) ?>">＋ <?= e(tr('افزودن روتر', 'Add router')) ?></a><?php endif;?></div>
<section class="panel"><div class="table-wrap"><table><thead><tr><th><?= e(tr('نام', 'Name')) ?></th><th><?= e(tr('نشانی', 'Address')) ?></th><th><?= e(tr('روش اتصال', 'Connection')) ?></th><th><?= e(tr('کاربران', 'Users')) ?></th><th><?= e(tr('وضعیت', 'Status')) ?></th><th><?= e(tr('آخرین همگام‌سازی', 'Last sync')) ?></th><th></th></tr></thead><tbody>
<?php foreach($routers as $router):$routerScheme=$router['use_tls']?'https':'http';$routerDefaultPort=($router['use_tls']&&(int)$router['port']===443)||(!$router['use_tls']&&(int)$router['port']===80);$routerAddress=$routerScheme.'://'.$router['host'].($routerDefaultPort?'':':'.$router['port']);?><tr><td><strong><?= e($router['name']) ?></strong><small class="table-sub"><?= $router['is_active']?e(tr('فعال','Enabled')):e(tr('غیرفعال','Disabled')) ?></small></td><td dir="ltr"><?= e($routerAddress) ?></td><td><?= $router['use_api_key']?'API Key':'Basic Auth' ?><small class="table-sub"><?= $router['verify_tls']?e(tr('بررسی گواهی روشن','TLS verified')):e(tr('بررسی گواهی خاموش','TLS unverified')) ?></small></td><td><?= fa_digits($router['user_count']) ?></td><td><span class="badge <?= badge_class($router['last_status']) ?>"><?= e(status_text($router['last_status'])) ?></span></td><td><?= e($router['last_sync_at']?:'—') ?></td><td><div class="row-actions">
    <?php if(Auth::canWrite()):?><form method="post" action="<?= e(url('router-sync')) ?>"><?= csrf_field() ?><input type="hidden" name="id" value="<?= e($router['id']) ?>"><button class="button small ghost" title="<?= e(tr('دریافت کاربران و اطلاعات روتر','Import router users and data')) ?>"><?= e(tr('همگام‌سازی','Sync')) ?> ↻</button></form><?php endif;?>
    <?php if(Auth::isSuperadmin()):?><form method="post" action="<?= e(url('router-test')) ?>"><?= csrf_field() ?><input type="hidden" name="id" value="<?= e($router['id']) ?>"><button class="button small ghost"><?= e(tr('آزمون','Test')) ?></button></form><a class="button small ghost" href="<?= e(url('router-form',['id'=>$router['id']])) ?>"><?= e(tr('ویرایش','Edit')) ?></a><form method="post" action="<?= e(url('router-delete')) ?>" data-confirm="<?= e(tr('روتر حذف شود؟','Delete this router?')) ?>"><?= csrf_field() ?><input type="hidden" name="id" value="<?= e($router['id']) ?>"><button class="button small danger-text">×</button></form><?php endif;?>
</div></td></tr><?php endforeach;?>
<?php if(!$routers):?><tr><td colspan="7" class="empty"><?= e(tr('هیچ روتری ثبت نشده است.','No routers found.')) ?></td></tr><?php endif;?></tbody></table></div></section>
